// 1. enum: a type AND a runtime object
enum Status {
  Pending = "pending",
  Paid = "paid",
  Shipped = "shipped",
}
function label(s: Status) { return s.toUpperCase(); }
label(Status.Paid);   // OK
label("paid");        // error: "paid" is not assignable to Status

// 2. union of literals: type only
type OrderStatus = "pending" | "paid" | "shipped";
function label2(s: OrderStatus) { return s.toUpperCase(); }
label2("paid");       // OK, and autocomplete still lists the options

const ORDER_STATUSES = ["pending", "paid", "shipped", "cancelled"] as const;
type OrderStatus = (typeof ORDER_STATUSES)[number];

function isOrderStatus(value: string): value is OrderStatus {
  return (ORDER_STATUSES as readonly string[]).includes(value);
}

// A transition table keyed by the union: the compiler checks every key.
const NEXT: Record<OrderStatus, Partial<Record<"pay" | "ship" | "cancel", OrderStatus>>> = {
  pending: { pay: "paid", cancel: "cancelled" },
  paid: { ship: "shipped", cancel: "cancelled" },
  shipped: {},
  cancelled: {},
};
